    {
      "card_ids": ["C02"],
      "claim": "The closest analogue (similarity 0.70), a 4-(2-fluoroethoxy)benzyl piperazine with a phenylpropyl substituent, showed high brain uptake and a high brain-to-blood ratio in mice and was not a P-gp substrate; this directly supports CNS access for the query, which retains the same fluoroethoxybenzyl-piperazine core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A related fluoroethoxybenzyl piperidine tracer crossed the BBB rapidly with 3.67 %ID brain uptake in rats, supporting that the fluoroethoxybenzyl piperazine/piperidine motif confers brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A close fluoroethoxybenzyl-piperidine analogue showed excellent initial brain uptake and slow washout in mice, reinforcing the CNS-penetrant phenotype of this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "JNJ-5207852, a moderately lipophilic bis-piperidine phenylpropyl ether, crossed the BBB and accumulated to high persistent brain levels in rats and mice, supporting that similar piperazine/piperidine architectures access the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A benzamide with a 1-benzyl-4-piperidinyl group showed significant and lasting high brain uptake in mice, indicating that amide-containing piperidine/piperazine analogues can still be CNS penetrant.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Roxatidine, a more polar amide-ether piperidine, showed only trace CSF exposure in humans (CSF:plasma 0–0.089), providing a contradictory low-CNS example, but its low similarity and much higher polarity limit transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "4-Phenylbutyric acid had very low brain uptake in primates, but as a carboxylic acid with low similarity it is a weak contradictory anchor and does not outweigh the close CNS-penetrant analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: the query is a close analogue of a fluoroethoxybenzyl-piperazine CNS penetrant with high brain uptake and no P-gp efflux; supporting evidence from related piperazine/piperidine and amide-containing CNS tracers outweighs weak contradictory polar/carboxylic-acid examples.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule",
    "Amide-for-amine substitution may alter basicity and transporter liability relative to the closest analogue",
    "No human data for the query or its closest analogue"
  ],
